<?php
require_once 'config.php';
$children = $pdo->query("SELECT c.*, p.name AS parent_name FROM children c LEFT JOIN parents p ON c.parent_id=p.id ORDER BY c.id DESC")->fetchAll();
$parents = $pdo->query("SELECT * FROM parents ORDER BY name")->fetchAll();
$staff = $pdo->query("SELECT * FROM staff ORDER BY name")->fetchAll();
$attendance = $pdo->query("SELECT a.*, c.name AS child_name FROM attendance a JOIN children c ON a.child_id=c.id ORDER BY a.date DESC LIMIT 8")->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CareTrack | Childcare Management</title><link rel="stylesheet" href="assets/style.css"></head>
<body><header><div class="brand">🧸 CareTrack</div><nav><a href="#dashboard">Dashboard</a><a href="#children">Children</a><a href="#parents">Parents</a><a href="#staff">Staff</a><a href="#attendance">Attendance</a></nav></header>
<main id="dashboard"><section class="welcome"><div><p class="eyebrow">CHILDCARE MANAGEMENT SYSTEM</p><h1>Care that keeps<br><span>every little step</span> on track.</h1><p>Manage child profiles, parent contacts, staff and daily attendance in one place.</p></div><div class="welcome-icon">🌱</div></section>
<section class="stats"><article><span>Children enrolled</span><strong><?= count($children) ?></strong></article><article><span>Parents registered</span><strong><?= count($parents) ?></strong></article><article><span>Staff members</span><strong><?= count($staff) ?></strong></article></section>
<section class="panel" id="children"><div class="section-title"><div><p class="eyebrow">DIRECTORY</p><h2>Children</h2></div><a class="button" href="child_add.php">+ Add child</a></div>
<div class="table-wrap"><table><thead><tr><th>Name</th><th>Age</th><th>Parent / Guardian</th><th>Actions</th></tr></thead><tbody><?php foreach($children as $c): ?><tr><td><?= htmlspecialchars($c['name']) ?></td><td><?= (int)$c['age'] ?></td><td><?= htmlspecialchars($c['parent_name'] ?? '—') ?></td><td><a href="child_delete.php?id=<?= $c['id'] ?>" onclick="return confirm('Delete this child record?')">Delete</a></td></tr><?php endforeach; ?><?php if(!$children): ?><tr><td colspan="4">No child records yet. Add your first child.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="grid"><section class="panel" id="parents"><div class="section-title"><div><p class="eyebrow">CONTACTS</p><h2>Parents</h2></div><a class="button secondary" href="parent_add.php">+ Add</a></div><ul class="simple-list"><?php foreach($parents as $p): ?><li><b><?= htmlspecialchars($p['name']) ?></b><small><?= htmlspecialchars($p['phone']) ?> · <?= htmlspecialchars($p['email']) ?></small></li><?php endforeach; ?><?php if(!$parents): ?><li>No parent records yet.</li><?php endif; ?></ul></section>
<section class="panel" id="staff"><div class="section-title"><div><p class="eyebrow">TEAM</p><h2>Staff</h2></div><a class="button secondary" href="staff_add.php">+ Add</a></div><ul class="simple-list"><?php foreach($staff as $s): ?><li><b><?= htmlspecialchars($s['name']) ?></b><small><?= htmlspecialchars($s['role']) ?></small></li><?php endforeach; ?><?php if(!$staff): ?><li>No staff records yet.</li><?php endif; ?></ul></section></div>
<section class="panel" id="attendance"><div class="section-title"><div><p class="eyebrow">DAILY RECORD</p><h2>Recent attendance</h2></div><a class="button" href="attendance_add.php">+ Mark attendance</a></div><div class="table-wrap"><table><thead><tr><th>Child</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($attendance as $a): ?><tr><td><?= htmlspecialchars($a['child_name']) ?></td><td><?= htmlspecialchars($a['date']) ?></td><td><span class="badge"><?= htmlspecialchars($a['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$attendance): ?><tr><td colspan="3">Attendance has not been recorded.</td></tr><?php endif; ?></tbody></table></div></section>
<footer>CareTrack · Childcare Management System · Academic project prototype</footer></main></body></html>